def hydrate_time(nanoseconds, tz=None):
    """
    Creates a :class:`~datetime.time` object from the given nanoseconds.

    :param nanoseconds: The nanoseconds to convert.
    :param tz: The timezone, defaults to None.
    :return: Time
    """
    if tz is not None:
        return datetime.time(nanoseconds=nanoseconds, tzinfo=tz)
    else:
        return datetime.time(nanoseconds=nanoseconds)

