    return {v: versions[v] for v in supported_versions}

def unit_of_work(metadata=None, timeout=None):
    # Check if metadata and timeout are valid
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("Metadata must be a dictionary")
    if timeout is not None and not isinstance(timeout, float) and timeout != 0:
        raise TypeError("Timeout must be a float or None")

    # If a timeout is specified, check that it is a positive value
    if timeout is not None and timeout < 0:
        raise ValueError("Timeout must be a positive value")

    # If metadata and timeout are valid, add them to the decorator
    def decorator(func):
        # Add a name to the transaction so that it can be identified and logged
        func.__name__ = func.__name__ + "_" + hex(id(func))

        # Add the metadata to the transaction, if any
        if metadata is not None:
            func.metadata = metadata

        # Add the timeout to the transaction, if any
        if timeout is not None:
            func.timeout = timeout

        # Add the new decorator method to the function
        def decorator_method(self, *args):
            # Run the transaction
            result = func(self, *args)

            # Return the result
            return result

        # Add the new decorator method to the function
        decorated_function = decorator_method

        # Return the new decorated function
        return decorated_function

