    """Dynamically create a Point subclass.

    Args:
        name (str): The name of the Point subclass.
        fields (list): The fields of the Point subclass.
        srid_map (dict): A dictionary mapping SRID strings to WKT strings.

    Returns:
        A dynamically created Point subclass.
    """

    class PointType(Point):
        """A dynamically created Point subclass."""

        __slots__ = ()

        def __new__(cls, *coords, srid=4326):
