def _inline_r_setup(code: str) -> str:
    """
    Some behavior of R cannot be configured via env variables, but can only be configured via R options once R has started. These are set here.
    """
    # Set R options
    code = f"""
    {{
        options( número.íntegers = "long.vector" );
        options( warnings = -1 );
        options( useFancyQuotes = FALSE );
        options( editor = "streamedit" );
        options( prompt = "> " );
        options( menu.graphics = FALSE );
        options( toolbar = FALSE );
        options( file.edit = TRUE );
        options( help_type = "text" );
    }}"""
    # STARTBLOCK appends the supplied code to the current R session
    code_str = f"STARTBLOCK {code}"
    # ENDBLOCK closes the STARTBLOCK
    code_str = f"{code_str} ENDBLOCK"
    return code_str

