class TargetClassImpl(_PyImplementation, _FallbackImplementation):
    """
    The target implementation to use for generating code.
    Note that this class should not be used externally, but should instead be accessed through the
    `_getTargetClass` method.
    """

    @staticmethod
    def python_implementation() -> str:
        return f'Py{_PyImplementation.NAME}'

    @staticmethod
    def fallback_implementation() -> str:
        return f'Fallback{_FallbackImplementation.NAME}'

    def getImplementationName(self) -> str:
        if self.is_target_implementation():
            return self.python_implementation()
        else:
            return self.fallback_implementation()

    @staticmethod
    def from_name(name: str) -> _TargetClassImpl:
        if name in _PyImplementation.NAMES:
            return _PyImplementation()
        elif name in _FallbackImplementation.NAMES:
            return _FallbackImplementation()
        else:
            raise ValueError("Unknown implementation name")

    def is_target_implementation(self) -> bool:
        return self.NAME in _getTargetClass().NAMES

    def getTargetClass(self) -> Type[_TargetClass]:
        if self.is_target_implementation():
            return _getTargetClass()
        else:
            raise ValueError("Not implemented for this implementation")

    @classmethod
    def get_target_class_name(cls) -> str:
        return _getTargetClass().__name__

