    """
    Reduce a list of base classes to its ordered minimum equivalent.
    """
    seen = set()
    while True:
        new_classes = []
        for cls in classes:
            if cls not in seen:
                seen.add(cls)
                new_classes.append(cls)
        if len(new_classes) == len(classes):
            break
        classes = new_classes
    return classes

