def normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if isinstance(sequence, (list, tuple, set)):
        for v in sequence:
            normalizeargs(v, output)
    elif isinstance(sequence, Mapping):
        for key, value in sequence.items():
            normalizeargs(value, output)
    else:
        cls = sequence.__class__
        if not (Interface in cls.__mro__ or Implements in cls.__mro__):
            output.append(sequence)

