def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if first_level:
        observer_schema = copy.deepcopy(manifest_dict)
        for key in KubeObservationSchemas.RESOURCE_MAP:
            if key in observer_schema:
                observer_schema[key] = manifest_dict[key]
        return observer_schema
    else:
        observer_schema = {}
        for key, value in manifest_dict.items():
            if isinstance(value, dict):
                observer_schema[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                observer_schema[key] = [generate_default_observer_schema_dict(item, first_level=False) for item in value]
            else:
                observer_schema[key] = None
        return observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate part of a default ``observer_schema`` from part of a Kubernetes resource.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a resource), the values of the identifying fields are copied from the manifest file.
    """

    def nest(value, depth=0):
        if isinstance(value, dict):
            return {
                key: nest(item, depth + 1) for key, item in value.items()
            }
        elif isinstance(value, list):
            return [
                nest(item, depth + 1) for item in value
            ]
        else:
            return None

    generated_dict = {key: nest(value) for key, value in manifest_dict.items()}

    if first_level:
        identifying_fields = ("apiVersion", "kind")
        for key in identifying_fields:
            generated_dict[key] = manifest_dict[key]

    return generated_dict

