    This function is called recursively to update a partial last applied manifest from a partial Kubernetes response

    Args:
        last_applied_manifest (list): Partial last applied manifest being updated
        observer_schema (list): Partial observer schema
        response (list): Partial response from the Kubernetes API

    This function iterates over all observed fields and initialize their value in the last applied manifest if they are not yet present
    """
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest[field] = []
        if field in response:
            if isinstance(last_applied_manifest[field], list):
                if isinstance(response[field], list):
                    for item in response[field]:
                        if item not in last_applied_manifest[field]:
                            last_applied_manifest[field].append(item)
            else:
                # If the field is a scalar, we update it with the response
                last_applied_manifest[field] = response[field]

    # If the response is a list, we update the last applied manifest with the new items
    if isinstance(response, list):
        for item in response:
            if item not in last_applied_manifest:
                last_applied_manifest.append(item)

