def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Update a partial last_applied_manifest from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial last_applied_manifest
        observer_schema (dict): partial observer_schema
        response (dict): partial Kubernetes response

    Raises:
        KeyError: If an observed field is not present in the Kubernetes response

    This function goes through all observed fields and initializes their value in
    last_applied_manifest if they are not yet present

    """
    for field_name in observer_schema:
        if field_name not in response:
            raise KeyError(f"Observed field {field_name} is not present in the Kubernetes response")

        field_info = observer_schema[field_name]
        new_value = response[field_name]

        if field_info["type"] == "dict":
            if field_name not in last_applied_manifest:
                last_applied_manifest[field_name] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field_name], field_info["observer"], new_value)
        elif field_info["type"] == "list":
            if field_name not in last_applied_manifest:
                last_applied_manifest[field_name] = []
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field_name], field_info["observer"], new_value)
        else:
            last_applied_manifest[field_name] = new_value
    return last_applied_manifest

