import zipfile

def _explore_zipfile(zip_path):
    zip_file = zipfile.ZipFile(zip_path)
    packages_data = {}

    for xml_file in zip_file.namelist():
        if not xml_file.endswith('.xml'):
            continue

        basename = os.path.basename(xml_file)
        package_name = basename.rsplit('.', 1)[0]
        if package_name not in packages_data:
            packages_data[package_name] = {}

        with zip_file.open(xml_file) as xml_file_obj:
            content = xml_file_obj.read()
            packages_data[package_name][basename] = content.decode('utf-8')

    return packages_data

def _explore_zipfile(zip_path):
    ZipFile = zipfile.ZipFile(zip_path)
    zip_contents = ZipFile.infolist()
    package_dict = {}
    for file in zip_contents:
        file_name = file.filename
        if file_name.endswith('/'):
            continue
        else:
            package_key = file_name.rpartition('/')[0]
            if package_key != '':
                file_contents = ZipFile.read(file_name)
                if package_key in package_dict:
                    package_dict[package_key].append(file_name)
                else:
                    package_dict[package_key] = [file_name]

        return package_dict

