def _extract_number_and_supplement_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    """
    issue_content = issue.text_content()

    supplement_match = re.search(r'(?P<supplement>\d+ Suppl(?:\.\d+)?)', issue_content)
    if supplement_match:
        supplement = supplement_match.group('supplement')

    number_match = re.search(r'(?P<number>\d+(?: Suppl\.\d+)?)', issue_content)
    if number_match:
        number = number_match.group('number')

    return {'supplement': supplement, 'number': number}

