    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if "&" in arg:
            lhs, rhs = arg.split("&")
            if "|" in lhs:
                lhs_op, lhs_arg = lhs.split("|")
                if lhs_op == "A":
                    lhs = lhs_arg
                elif lhs_op == "~A":
                    lhs = "~" + lhs_arg
                else:
                    lhs = "(" + lhs + ")"
            if "|" in rhs:
                rhs_op, rhs_arg = rhs.split("|")
                if rhs_op == "A":
                    rhs = rhs_arg
                elif rhs_op == "~A":
                    rhs = "~" + rhs_arg
                else:
                    rhs = "(" + rhs + ")"
            result.append(lhs + " & " + rhs)
        elif "|" in arg:
