                if lhs_op == "A":
                    lhs = lhs_arg
                elif lhs_op == "~A":
                    lhs = "~" + lhs_arg
                else:
                    lhs = "(" + lhs + ")"
            if "&" in rhs:
                rhs_op, rhs_arg = rhs.split("&")
                if rhs_op == "A":
                    rhs = rhs_arg

def absorb(self, args):
    # using a set to prevent duplicates in the output
    result = set()

    # iterate over all pairs of arguments
    for i, arg_left in enumerate(args):
        for arg_right in args[i + 1:]:
            if arg_left & arg_right == arg_left:
                # absorption case: add the left argument to the result
                result.add(arg_left)
            elif arg_left & arg_right == arg_right:
                # negative absorption case: add the right argument to the result
                result.add(arg_right)

    return list(result)

