def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    # Run each command in the list
    for cmd in commands:
        # Set up the command and arguments
        command = cmd
        arguments = args

        # Set up the working directory
        if cwd:
            cwd = cwd
        else:
            cwd = subprocess.getcwd()

        # Set up the environment variables
        if env:
            env = env
        else:
            env = dict(os.environ)

        # Set up the stdout and stderr buffers
        buf = subprocess.PIPE
        if hide_stderr:
            err = None
        else:
            err = buf

        # Run the command
        process = subprocess.Popen(command, buf, arguments, cwd, env, stdin, stdout, stderr)
        if verbose:
            print("Running command: {}".format(command))
        try:
            output, errors = process.communicate()
            returncode = process.returncode
        except:
            raise subprocess.CalledProcessError(returncode, command)
        if verbose:
            print("Command output: {}".format(output))
        if hide_stderr:
            if errors:
                print("Command errors: {}".format(errors))
        if returncode != 0:
            raise subprocess.CalledProcessError(returncode, command)
    return output

