def process_text_links(text):
  """Process links in text, adding some attributes and linkifying textual links."""
  import re
  from urllib.parse import urlparse

  # TODO: Handle invalid inputs and runtime issues with exception-handling behavior as appropriate

  # Match links in the form "<http://example.com>" or "<foo@example.com>"
  link_re = re.compile(r"<(.*?)>")

  # Match URLs in the form "http://example.com" or "https://example.com"
  url_re = re.compile(r"https?://\S+")

  # Match emails in the form "foo@example.com"
  email_re = re.compile(r"[\w.+-]+@[\w-]+\.[\w]+")

  # Match non-link text
  text_re = re.compile(r"\S+?")

  # Match whitespace
  whitespace_re = re.compile(r"\s+")

  def linkify(m):
    url = m.group(1)
    if url_re.match(url):
      return "<a href='{}'>{}</a>".format(url, url)
    elif email_re.match(url):
      return "<a href='mailto:{}'>{}</a>".format(url, url)
    else:
      return url

  def add_attributes(m):
    text = m.group(1)
    if url_re.match(text):
      return "<a href='{}' target='_blank'>{}</a>".format(text, text)
    elif email_re.match(text):
      return "<a href='mailto:{}' target='_blank'>{}</a>".format(text, text)
    else:
      return text

  output = []
  for match in link_re.finditer(text):
    text = match.group(1)
    url = urlparse(text).geturl()
    if url_re.match(text):
      output.append(linkify(match))
    elif email_re.match(text):
      output.

