def test_tag(tag: str) -> bool:
    """
    Test a word whether it could be accepted as a tag.

    :param tag: the word to be tested
    :type tag: str
    :return: whether the word is a valid tag
    :rtype: bool
    """
    if len(tag) == 0:
        return False

    if tag[0] != '#':
        return False

    for i in range(1, len(tag)):
        if not tag[i].isalnum() and tag[i] != '-' and tag[i] != '_':
            return False

    return True

def test_tag(tag: str) -> bool:
    """
    Test a word whether it could be accepted as a tag.

    :param tag: the word to test
    :type tag: str
    :return: whether the word could be accepted as a tag
    :rtype: bool
    """
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    if len(tag) == 0:
        return False
    if tag[0] in string.digits or tag[0] in string.punctuation:
        return False
    for c in tag:
        if c not in string.ascii_letters and c not in string.digits and c not in string.punctuation:
            return False
    return True

