            return tag.isalnum()
    return False

def xml_children_as_dict(node):
    """
    Return a dictionary containing the children of the node.

    Keyword arguments:
    node -- The XML node to extract the children from.
    """
    children = {}
    for child in node.childNodes:
        if child.nodeType == child.ELEMENT_NODE:
            children[child.tagName] = child.childNodes[0].nodeValue
    return children

def xml_children_as_dict(node):
    children_dict = {}
    for child in node.getchildren():
        tag = child.tag
        if tag not in children_dict:
            children_dict[tag] = []
        children_dict[tag].append(child.text)
    return children_dict

def xml_children_as_dict(node):
    children = node.findall("./*")
    children_dict = {}
    for child in children:
        children_dict[child.tag] = child.text
    return children_dict

def _xml_children_as_dict(node):
    element_dict = {}
    for element in node.find_all()]
        key = element.get_text().strip()
        element_dict[key] = [_xml_children_as_dict(element)]
    return element_dict

