def parse_nodeinfo_document(document):
    """
    Parse a NodeInfo document into a dictionary.

    See spec: http://nodeinfo.diaspora.software

    :arg document: The NodeInfo document as a string
    :returns: dict
    """
    try:
        data = json.loads(document)
    except JSONDecodeError:
        raise DocumentParseError("Failed to parse NodeInfo document: not valid JSON")
    required_fields = [
        "nodeinfo",
        "nodeinfo.server",
        "nodeinfo.server.baseUrl",
        "nodeinfo.server.name",
        "nodeinfo.server.software",
        "nodeinfo.server.version",
        "nodeinfo.openRegistrations",
    ]
    for field in required_fields:
        if field not in data:
            raise DocumentInvalidError(f"Required field '{field}' not found in NodeInfo document")
    return data


