def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        data = json.loads(document)
        return {
            "hcard_url": data.get("hcard_url"),
            "microformats_url": data.get("microformats_url"),
            "host_meta": data.get("host-meta"),
        }
    except json.JSONDecodeError:
        # Parse as XRD (old format)
        doc = lxml.etree.fromstring(document)
        results = {}
        for entry in doc.findall(".//{urn:ietf:params:xml:ns:xrd-1.0}Link"):
            rel = entry.get("rel")
            if rel:
                results[rel] = entry.get("href")
        return results

def parse_diaspora_webfinger(document: str) -> Dict:
    if document.startswith('<?xml'):
        root = ET.fromstring(document)
        url = root.find('./XRD/URI').text
        links = []
        for link in root.findall('./XRD/Link'):
            links.append(
                {
                    'rel': link.attrib['rel'],
                    'href': link.text,
                    'type': link.attrib['type']
                }
            )
    else:
        obj = json.loads(document)
        url = obj['subject']
        links = obj['links']
    return {
        'url': url,
        'links': links
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if "properties" in data:
            return data["properties"]
        return data["links"][0]["properties"]
    except (json.JSONDecodeError, KeyError, IndexError):
        xrd = defusedxml.ElementTree.fromstring(document)
        return {link.attrib["rel"]: link.attrib["href"] for link in xrd.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")}
    except (AttributeError, xml.etree.ElementTree.ParseError):
        logger.error("parse_diaspora_webfinger: unable to parse webfinger document: %s", document)
        raise Exception("Failed to parse Diaspora webfinger document")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html

    :param document: str
    :return: Dict
    """
    # Check if the document is in JSON format (new) or XRD (old)
    try:
        return json.loads(document, object_hook=_parse_xrd_format)
    except json.JSONDecodeError:
        return _parse_xrd_format(json.loads(document))

def _parse_xrd_format(data: dict) -> Dict:
    """
    Parse Diaspora webfinger in XRD (old) format.

    Args:
        data: dict

    Returns:
        Dict
    """
    links = []
    for link in data["Link"]:
        links.append({
            "rel": link["rel"]["content"],
            "template": link["template"],
            "type": link["type"]["content"]
        })
    return {
        "alias": data["XRD"]["Alias"],
        "subject": data["XRD"]["Subject"],
        "published": data["XRD"]["Published"],
        "links": links
    }

