    The `settings_dirs` parameter is a list of directories to search for files.

    The `spec_option` parameter is a string that specifies the file name pattern to search for.

    The output is a list of fully qualified file names that match the given pattern.
    """
    try:
        file_names = []
        for settings_dir in settings_dirs:
            for root, dirs, files in os.walk(settings_dir):
                for file in files:
                    if fnmatch(file, spec_option):
                        file_names.append(os.path.join(root, file))
        return sorted(file_names)
    except OSError:
        return []

