def validate_from_content(spec_content):
    """Validates that spec (YAML) content has all required fields

    :param spec_content: Content of spec file
    :raise IRValidatorException: When mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    # Load the content of the spec file as a dictionary
    content_dict = yaml.load(spec_content, Loader=yaml.FullLoader)

    # Check for missing required fields
    for field in REQUIRED_FIELDS:
        if field not in content_dict:
            raise IRValidatorException(f"Missing required field: {field}")

    # Check that the 'type' field is valid
    if 'type' in content_dict:
        if content_dict['type'] not in IR_TYPES:
            raise IRValidatorException(f"Invalid 'type' field: {content_dict['type']}")

    # Check that all fields are valid
    for field, value in content_dict.items():
        if field not in REQUIRED_FIELDS and field not in OPTIONAL_FIELDS:
            raise IRValidatorException(f"Invalid field: {field}")

    # Return the content dictionary
    return content_dict

def validate_from_content(spec_content):
