def validate_from_content(spec_content):
    """Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of spec file.
    :raise IRValidatorException: When mandatory data is missing in spec file.
    :return: Dictionary with data loaded from a spec (YAML) file.
    """
    spec = yaml.safe_load(spec_content)

    # Check that all mandatory fields are defined
    for field in REQUIRED_FIELDS:
        if field not in spec:
            raise IRValidatorException("Mandatory field '{}' is missing in spec file.".format(field))

    # Check that all field values are valid
    for field, value in spec.items():
        if field in ENUMERABLE_FIELDS:
            if value not in ENUMERABLE_VALUES[field]:
                raise IRValidatorException("Invalid value '{}' for field '{}' in spec file.".format(value, field))

    # Check that spec content is a valid JSON
    try:
        json.dumps(spec)
    except json.JSONDecodeError:
        raise IRValidatorException("Spec content is not valid JSON")

    return spec

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.load(f)

        if not data:
            raise LookupError('No data found in the YAML file')

        # Check for mandatory fields
        if 'mandatory_field1' not in data:
            raise IRValidatorException('Mandatory field "mandatory_field1" missing in the YAML file')

        if 'mandatory_field2' not in data:
            raise IRValidatorException('Mandatory field "mandatory_field2" missing in the YAML file')

        # Check for optional fields
        if 'optional_field1' in data:
            if data['optional_field1'] is None or not isinstance(data['optional_field1'], str):
                raise IRValidatorException('Invalid value for optional_field1 in the YAML file')

        # Return the data loaded from the YAML file
        return data

    except (YAMLError, IOError) as e:
        raise IRValidatorException('There was a problem loading the YAML file: ' + str(e))

def include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.
    """
    for key, value in iteritems(parser_dict):
        if isinstance(value, str) and value.startswith('!'):
            include_file = value[1:]
            try:
                with open(include_file, 'r') as f:
                    value = f.read()
            except FileNotFoundError as ex:
                print(f'Unable to include file: {include_file}, cause: {ex}')
        parser_dict[key] = value

def include_groups(self, parser_dict):
    """
    Resolves the `include` dict directive in the spec files.

    :param dict parser_dict:
    """
    includes = parser_dict.get('Include')
    if includes:
        for include in includes:
            includes.update(include)
    return includes

def include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    :param dict parser_dict:
    """
    includes = parser_dict.get('include', {})
    if includes:
        for include in includes.values():
            if isinstance(include, str):
                include_config = self.read_config(include, parser_dict)
                self._include_groups(include_config)
            else:
                self.error(f"Invalid include dict value {include}")

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of default values for each argument, with the argument name as the key and the default value as the value.
    """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise InvalidArgumentTypeError(f'Unable to resolve default value for argument {arg.name} of type {type(arg)}')

        # if there is a default set, add it to the defaults dict
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # if we have a dict option, resolve the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                defaults[arg.name] = self.get_spec_defaults(arg.scheme)
        # if we have a list option, resolve the defaults for its items.
        elif isinstance(arg, ListOption):
            if arg.items:
                defaults[arg.name] = [self.get_spec_defaults(item) for item in arg.items]
        # if we have a schema option, resolve the defaults for its schema.
        elif isinstance(arg, SchemaOption):
            if arg.schema:
                defaults[arg.name] = self.get_spec_defaults(arg.schema)
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of argument values, with the argument names as keys and their corresponding values as values.

    Raises:
        errors.InvalidArgumentError: If the argument name is not found in the spec or any other known argument source.
    """
    defaults = {}
    for name, arg in self.spec.arguments.items():
        try:
            value = arg.default
        except AttributeError:
            continue

        # If the argument has no default value, skip it
        if value is None:
            continue

        # If the argument has a value, add it to the defaults dictionary
        defaults[name] = value

    # Check if there are any default values specified in the spec's options.
    for option in self.spec.options:
        if option.dest in defaults:
            continue

        if option.default is not None:
            defaults[option.dest] = option.default

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: The resolved defaults for the current scheme.
    """
    defaults = {}
    for arg in self.args:
        if arg.source in ('spec', 'auto'):
            value = getattr(self.spec, arg.name)
        else:
            value = None

        # Check for missing values and update the spec
        if value is None and arg.required:
            raise errors.InvalidSpecError(
                f'Required argument {arg.name} is missing in the spec'
            )

        if value is not None:
            defaults[arg.name] = value

    # Update the spec with the resolved defaults
    for arg, value in defaults.items():
        setattr(self.spec, arg, value)

    return defaults

