def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    extra_vars = ensure_list_format(extra_vars)
    for var in extra_vars:
        if not isinstance(var, dict):
            raise ValueError(f"Invalid extra-var: {var}. Dictionary expected.")

        for key, value in var.items():
            if key not in vars_dict:
                vars_dict[key] = value
            elif isinstance(vars_dict[key], dict) and isinstance(value, dict):
                self.merge_extra_vars(vars_dict[key], value)
            elif isinstance(vars_dict[key], list) and isinstance(value, list):
                vars_dict[key].extend(value)
            else:
                raise ValueError(f"Invalid extra-var: {var}. Cannot merge values of type {type(vars_dict[key])} and {type(value)}.")

    return vars_dict

def ensure_list_format(extra_vars):
    if not extra_vars:
        return []
    elif isinstance(extra_vars, str):
        try:
            return json.loads(extra_vars)
        except json.JSONDecodeError:
            raise ValueError(f"Invalid extra-vars: {extra_vars}. Cannot parse JSON object.")
    elif isinstance(extra_vars, list):
        return extra_vars
    else:
        raise ValueError(f"Invalid extra-vars: {extra_vars}. List or string expected.")

